CREATE TYPE public.app_role AS ENUM ('super_admin','product_admin','order_admin','content_admin');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE NOT NULL, role public.app_role NOT NULL, UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE FUNCTION public.can_manage(_area text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND (role='super_admin' OR role::text=_area||'_admin')) $$;
REVOKE ALL ON FUNCTION public.can_manage(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.can_manage(text) TO authenticated,service_role;
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '' CHECK(length(full_name)<=100), phone text DEFAULT '' CHECK(length(phone)<=20), company text DEFAULT '' CHECK(length(company)<=200), gstin text DEFAULT '' CHECK(length(gstin)<=15));
GRANT SELECT,INSERT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.can_manage('order'));
CREATE POLICY profile_insert ON public.profiles FOR INSERT TO authenticated WITH CHECK(id=auth.uid()); CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id,full_name) VALUES(NEW.id,left(coalesce(NEW.raw_user_meta_data->>'full_name',''),100)); RETURN NEW; END $$;
CREATE TRIGGER apex_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.categories (id text PRIMARY KEY, name text NOT NULL CHECK(length(name)<=100), image_key text NOT NULL DEFAULT '', description text NOT NULL DEFAULT '', sort_order integer NOT NULL DEFAULT 0);
GRANT SELECT ON public.categories TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.categories TO authenticated; GRANT ALL ON public.categories TO service_role;
ALTER TABLE public.categories ENABLE ROW LEVEL SECURITY; CREATE POLICY category_read ON public.categories FOR SELECT TO anon,authenticated USING(true); CREATE POLICY category_manage ON public.categories FOR ALL TO authenticated USING(public.can_manage('product')) WITH CHECK(public.can_manage('product'));
CREATE TABLE public.products (id text PRIMARY KEY, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 200), source_name text NOT NULL DEFAULT '', category_id text REFERENCES public.categories(id), brand text NOT NULL DEFAULT '', sku text NOT NULL UNIQUE, description text NOT NULL DEFAULT '', specs jsonb NOT NULL DEFAULT '{}', image_key text NOT NULL DEFAULT '', image_url text, price numeric(12,2) CHECK(price>=0), gst_rate numeric(5,2) CHECK(gst_rate>=0 AND gst_rate<=100), stock integer CHECK(stock>=0), unit text NOT NULL DEFAULT 'NOS', min_quantity integer NOT NULL DEFAULT 1 CHECK(min_quantity>0), bulk_tiers jsonb NOT NULL DEFAULT '[]', featured boolean NOT NULL DEFAULT false, published boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.products TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.products TO authenticated; GRANT ALL ON public.products TO service_role;
ALTER TABLE public.products ENABLE ROW LEVEL SECURITY; CREATE POLICY products_public ON public.products FOR SELECT TO anon,authenticated USING(published); CREATE POLICY products_admin ON public.products FOR ALL TO authenticated USING(public.can_manage('product')) WITH CHECK(public.can_manage('product'));
CREATE INDEX products_category_idx ON public.products(category_id);
CREATE TABLE public.cart_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,product_id text REFERENCES public.products(id) ON DELETE CASCADE NOT NULL,quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 100000),UNIQUE(user_id,product_id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.cart_items TO authenticated; GRANT ALL ON public.cart_items TO service_role; ALTER TABLE public.cart_items ENABLE ROW LEVEL SECURITY; CREATE POLICY cart_owner ON public.cart_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX cart_user_idx ON public.cart_items(user_id);
CREATE TABLE public.wishlist_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,product_id text REFERENCES public.products(id) ON DELETE CASCADE NOT NULL,UNIQUE(user_id,product_id));
GRANT SELECT,INSERT,DELETE ON public.wishlist_items TO authenticated; GRANT ALL ON public.wishlist_items TO service_role; ALTER TABLE public.wishlist_items ENABLE ROW LEVEL SECURITY; CREATE POLICY wishlist_owner ON public.wishlist_items FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX wishlist_user_idx ON public.wishlist_items(user_id);
CREATE TABLE public.addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,name text NOT NULL CHECK(length(name)<=100),phone text NOT NULL CHECK(length(phone)<=20),line1 text NOT NULL CHECK(length(line1)<=200),line2 text NOT NULL DEFAULT '' CHECK(length(line2)<=200),city text NOT NULL CHECK(length(city)<=100),state text NOT NULL CHECK(length(state)<=100),pin text NOT NULL CHECK(pin~'^[1-9][0-9]{5}$'),country text NOT NULL DEFAULT 'India');
GRANT SELECT,INSERT,UPDATE,DELETE ON public.addresses TO authenticated; GRANT ALL ON public.addresses TO service_role; ALTER TABLE public.addresses ENABLE ROW LEVEL SECURITY; CREATE POLICY address_owner ON public.addresses FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid()); CREATE INDEX address_user_idx ON public.addresses(user_id);
CREATE TABLE public.enquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN ('bulk','contact')),name text NOT NULL CHECK(length(name)<=100),email text NOT NULL CHECK(length(email)<=255),phone text NOT NULL DEFAULT '' CHECK(length(phone)<=20),company text NOT NULL DEFAULT '' CHECK(length(company)<=200),gstin text NOT NULL DEFAULT '' CHECK(length(gstin)<=15),location text NOT NULL DEFAULT '' CHECK(length(location)<=300),subject text NOT NULL DEFAULT '' CHECK(length(subject)<=200),message text NOT NULL DEFAULT '' CHECK(length(message)<=3000),items jsonb NOT NULL DEFAULT '[]',document_path text,status text NOT NULL DEFAULT 'New' CHECK(status IN ('New','Under Review','Quotation Sent','Accepted','Rejected','Converted to Order')),internal_notes text NOT NULL DEFAULT '',quotation jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.enquiries TO authenticated; GRANT ALL ON public.enquiries TO service_role; ALTER TABLE public.enquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY enquiry_read ON public.enquiries FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage('order')); CREATE POLICY enquiry_create ON public.enquiries FOR INSERT TO authenticated WITH CHECK(user_id=auth.uid() AND status='New' AND internal_notes='' AND quotation IS NULL); CREATE POLICY enquiry_manage ON public.enquiries FOR UPDATE TO authenticated USING(public.can_manage('order')) WITH CHECK(public.can_manage('order')); CREATE INDEX enquiry_user_idx ON public.enquiries(user_id);
CREATE TABLE public.orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,number text NOT NULL UNIQUE,total numeric(12,2) NOT NULL CHECK(total>=0),payment_status text NOT NULL DEFAULT 'pending',status text NOT NULL DEFAULT 'Order Placed',items jsonb NOT NULL,shipping_address jsonb NOT NULL,courier text,tracking_number text,estimated_delivery date,invoice_path text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,UPDATE ON public.orders TO authenticated; GRANT ALL ON public.orders TO service_role; ALTER TABLE public.orders ENABLE ROW LEVEL SECURITY; CREATE POLICY order_read ON public.orders FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.can_manage('order')); CREATE POLICY order_manage ON public.orders FOR UPDATE TO authenticated USING(public.can_manage('order')) WITH CHECK(public.can_manage('order')); CREATE INDEX orders_user_idx ON public.orders(user_id);
CREATE TABLE public.order_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES public.orders(id) ON DELETE CASCADE,status text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.order_status_history TO authenticated; GRANT ALL ON public.order_status_history TO service_role; ALTER TABLE public.order_status_history ENABLE ROW LEVEL SECURITY; CREATE POLICY order_history_read ON public.order_status_history FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.orders WHERE id=order_id AND (user_id=auth.uid() OR public.can_manage('order')))); CREATE INDEX history_order_idx ON public.order_status_history(order_id);
CREATE FUNCTION public.record_order_status() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO public.order_status_history(order_id,status) VALUES(NEW.id,NEW.status); END IF; RETURN NEW; END $$;
CREATE TRIGGER apex_order_history AFTER INSERT OR UPDATE ON public.orders FOR EACH ROW EXECUTE FUNCTION public.record_order_status();
CREATE TABLE public.cms_pages (slug text PRIMARY KEY,title text NOT NULL,body text NOT NULL DEFAULT '',published boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.cms_pages TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.cms_pages TO authenticated; GRANT ALL ON public.cms_pages TO service_role; ALTER TABLE public.cms_pages ENABLE ROW LEVEL SECURITY; CREATE POLICY cms_public ON public.cms_pages FOR SELECT TO anon,authenticated USING(published); CREATE POLICY cms_admin ON public.cms_pages FOR ALL TO authenticated USING(public.can_manage('content')) WITH CHECK(public.can_manage('content'));
CREATE TABLE public.blog_posts (slug text PRIMARY KEY,title text NOT NULL CHECK(length(title)<=200),excerpt text NOT NULL DEFAULT '',body text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',image_url text,published boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.blog_posts TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.blog_posts TO authenticated; GRANT ALL ON public.blog_posts TO service_role; ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY; CREATE POLICY blog_public ON public.blog_posts FOR SELECT TO anon,authenticated USING(published); CREATE POLICY blog_admin ON public.blog_posts FOR ALL TO authenticated USING(public.can_manage('content')) WITH CHECK(public.can_manage('content'));
CREATE TABLE public.coupons (code text PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('percentage','fixed')),value numeric NOT NULL CHECK(value>0),minimum_total numeric NOT NULL DEFAULT 0 CHECK(minimum_total>=0),expires_at timestamptz,usage_limit integer CHECK(usage_limit>0),active boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.coupons TO authenticated; GRANT ALL ON public.coupons TO service_role; ALTER TABLE public.coupons ENABLE ROW LEVEL SECURITY; CREATE POLICY coupons_admin ON public.coupons FOR ALL TO authenticated USING(public.can_manage('order')) WITH CHECK(public.can_manage('order'));
CREATE TABLE public.newsletter_subscribers (email text PRIMARY KEY CHECK(length(email)<=255),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,DELETE ON public.newsletter_subscribers TO authenticated; GRANT ALL ON public.newsletter_subscribers TO service_role; ALTER TABLE public.newsletter_subscribers ENABLE ROW LEVEL SECURITY; CREATE POLICY newsletter_admin ON public.newsletter_subscribers FOR SELECT TO authenticated USING(public.can_manage('content'));
CREATE TABLE public.submission_limits (fingerprint text PRIMARY KEY,last_submitted_at timestamptz NOT NULL DEFAULT now()); GRANT ALL ON public.submission_limits TO service_role; ALTER TABLE public.submission_limits ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.claim_submission(_fingerprint text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE claimed text; BEGIN INSERT INTO public.submission_limits(fingerprint) VALUES(_fingerprint) ON CONFLICT(fingerprint) DO UPDATE SET last_submitted_at=now() WHERE submission_limits.last_submitted_at < now()-interval '60 seconds' RETURNING fingerprint INTO claimed; RETURN claimed IS NOT NULL; END $$; REVOKE ALL ON FUNCTION public.claim_submission(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.claim_submission(text) TO service_role;
